:root {
  --ceremony-title-font: 'JeeshikaNilavu', 'JeeshikaTamil', sans-serif;
  --baby-name-tamil-font: 'JeeshikaMarutham', 'JeeshikaTamil', sans-serif;
}

/* CRITICAL: Enforce Natural Letter Spacing & Zero Uppercase on Tamil Text */
.font-tamil,
.font-tamil-body,
[lang="ta"] {
  font-family: 'JeeshikaMarutham', 'Anek Tamil', 'JeeshikaTamil', serif !important;
  letter-spacing: normal !important;
  word-spacing: normal !important;
  text-transform: none !important;
  font-feature-settings: "tml2" 1, "taml" 1, "abvs" 1, "psts" 1, "akhn" 1, "haln" 1 !important;
  -webkit-font-smoothing: antialiased;
}

/* CEREMONY TITLE FONT: High-Impact Bold Display */
.font-tamil-title,
.font-tamil-display {
  font-family: 'JeeshikaMarutham', 'Anek Tamil', 'JeeshikaNilavu', serif !important;
  letter-spacing: normal !important;
  word-spacing: normal !important;
  text-transform: none !important;
  font-feature-settings: "tml2" 1, "taml" 1, "abvs" 1, "psts" 1, "akhn" 1, "haln" 1 !important;
  -webkit-font-smoothing: antialiased;
}

.font-tamil-marutham {
  font-family: 'JeeshikaMarutham', sans-serif !important;
  letter-spacing: normal !important;
  text-transform: none !important;
}

.font-tamil-kurinji {
  font-family: 'JeeshikaKurinji', sans-serif !important;
  letter-spacing: normal !important;
  text-transform: none !important;
}

.font-tamil-mullai {
  font-family: 'JeeshikaMullai', sans-serif !important;
  letter-spacing: normal !important;
  text-transform: none !important;
}

.font-tamil-nilavu {
  font-family: 'JeeshikaNilavu', sans-serif !important;
  letter-spacing: normal !important;
  text-transform: none !important;
}

.font-tamil-ezhil {
  font-family: 'JeeshikaEzhil', sans-serif !important;
  letter-spacing: normal !important;
  text-transform: none !important;
}

.font-tamil-names,
.font-baby-tamil {
  font-family: var(--baby-name-tamil-font, 'JeeshikaMarutham', sans-serif) !important;
  letter-spacing: normal !important;
  text-transform: none !important;
  font-feature-settings: "tml2" 1, "taml" 1, "abvs" 1, "psts" 1, "akhn" 1, "haln" 1 !important;
  -webkit-font-smoothing: antialiased;
}